  1→import { Hono } from 'hono';
  2→import fs from 'fs';
  3→import os from 'os';
  4→import path from 'path';
  5→import { parseClaudeCodeSession } from '../import/parser.js';
  6→import { parseClaudeAiConversation } from '../import/claude-ai-parser.js';
  7→import { extractConversationsFromZip } from '../import/claude-ai-zip.js';
  8→import { importSession, findChannelByOriginalSessionId } from '../db/queries.js';
  9→import { MODEL_ALIASES, AVAILABLE_MODELS } from '@klatch/shared';
 10→import type { ModelId } from '@klatch/shared';
 11→
 12→// Max file size for imports (50 MB)
 13→const MAX_IMPORT_SIZE = 50 * 1024 * 1024;
 14→
 15→/** Expand ~ to home directory safely using os.homedir() */
 16→function expandHome(filePath: string): string {
 17→  if (filePath.startsWith('~/') || filePath === '~') {
 18→    return path.join(os.homedir(), filePath.slice(1));
 19→  }
 20→  return filePath;
 21→}
 22→
 23→/**
 24→ * Validate that a resolved path is an absolute path and doesn't escape
 25→ * via directory traversal. Returns the resolved path or null if invalid.
 26→ */
 27→function validateImportPath(filePath: string): string | null {
 28→  const resolved = path.resolve(filePath);
 29→  // Must be absolute (resolve guarantees this, but belt-and-suspenders)
 30→  if (!path.isAbsolute(resolved)) return null;
 31→  // Block obvious traversal patterns in the original input
 32→  if (filePath.includes('..')) return null;
 33→  return resolved;
 34→}
 35→
 36→const app = new Hono();
 37→
 38→/**
 39→ * POST /import/claude-code
 40→ *
 41→ * Import a Claude Code JSONL session file into Klatch as a new channel.
 42→ *
 43→ * Body: { sessionPath: string, channelName?: string }
 44→ * Returns: 201 with ImportResult, or 400/404/409 on error.
 45→ */
 46→app.post('/import/claude-code', async (c) => {
 47→  const { sessionPath, channelName } = await c.req.json<{
 48→    sessionPath: string;
 49→    channelName?: string;
 50→  }>();
 51→
 52→  if (!sessionPath) {
 53→    return c.json({ error: 'sessionPath is required' }, 400);
 54→  }
 55→
 56→  // Validate file extension
 57→  if (!sessionPath.endsWith('.jsonl')) {
 58→    return c.json({ error: 'File must be a .jsonl file' }, 400);
 59→  }
 60→
 61→  // Expand ~ and validate path
 62→  const expandedPath = validateImportPath(expandHome(sessionPath));
 63→  if (!expandedPath) {
 64→    return c.json({ error: 'Invalid file path' }, 400);
 65→  }
 66→
 67→  // Check file exists
 68→  if (!fs.existsSync(expandedPath)) {
 69→    return c.json({ error: 'File not found' }, 404);
 70→  }
 71→
 72→  // Check file size
 73→  const stat = fs.statSync(expandedPath);
 74→  if (stat.size > MAX_IMPORT_SIZE) {
 75→    return c.json({ error: `File too large (${Math.round(stat.size / 1024 / 1024)}MB). Maximum is ${MAX_IMPORT_SIZE / 1024 / 1024}MB.` }, 400);
 76→  }
 77→
 78→  // Parse the session
 79→  const session = await parseClaudeCodeSession(expandedPath);
 80→
 81→  // Validate non-empty
 82→  if (session.turns.length === 0) {
 83→    return c.json({ error: 'Session is empty — no conversation events found' }, 400);
 84→  }
 85→
 86→  // Check for duplicate import
 87→  if (session.sessionId) {
 88→    const existing = findChannelByOriginalSessionId(session.sessionId);
 89→    if (existing) {
 90→      return c.json({
 91→        error: 'This session has already been imported',
 92→        existingChannelId: existing.id,
 93→        existingChannelName: existing.name,
 94→      }, 409);
 95→    }
 96→  }
 97→
 98→  // Generate channel name if not provided
 99→  const name = channelName || generateChannelName(session.cwd, session.firstTimestamp);
100→
101→  // Resolve model: map legacy IDs to current ones
102→  const resolvedModel = resolveModel(session.model);
103→
104→  // Import into database
105→  const result = importSession({
106→    channelName: name,
107→    source: 'claude-code',
108→    sourceMetadata: {
109→      originalSessionId: session.sessionId,
110→      cwd: session.cwd,
111→      gitBranch: session.gitBranch,
112→      slug: session.slug,
113→      version: session.version,
114→      eventCount: session.eventCount,
115→      firstTimestamp: session.firstTimestamp,
116→      lastTimestamp: session.lastTimestamp,
117→      compactionSummary: session.compactionSummary,
118→      importedAt: new Date().toISOString(),
119→    },
120→    model: resolvedModel,
121→    turns: session.turns,
122→  });
123→
124→  return c.json({
125→    ...result,
126→    sessionId: session.sessionId,
127→    ...(session.skippedLines ? { skippedLines: session.skippedLines } : {}),
128→  }, 201);
129→});
130→
131→/**
132→ * Generate a channel name from the session's working directory and timestamp.
133→ * Format: "{project} — {YYYY-MM-DD}"
134→ */
135→function generateChannelName(cwd?: string, timestamp?: string): string {
136→  const project = cwd ? path.basename(cwd) : 'import';
137→  const date = timestamp
138→    ? timestamp.slice(0, 10)  // "2026-03-08T..." → "2026-03-08"
139→    : new Date().toISOString().slice(0, 10);
140→  return `${project} — ${date}`;
141→}
142→
143→/**
144→ * Resolve a Claude Code model ID to a Klatch-recognized model ID.
145→ * Falls back to DEFAULT_MODEL if unrecognized.
146→ */
147→function resolveModel(modelId?: string): ModelId | undefined {
148→  if (!modelId) return undefined;
149→  // Direct match
150→  if (modelId in AVAILABLE_MODELS) return modelId as ModelId;
151→  // Legacy alias
152→  if (modelId in MODEL_ALIASES) return MODEL_ALIASES[modelId];
153→  // Unrecognized — return undefined to use channel default
154→  return undefined;
155→}
156→
157→/**
158→ * POST /import/claude-ai
159→ *
160→ * Import conversations from a claude.ai email export ZIP file.
161→ * Supports both multipart file upload and JSON body with file path.
162→ *
163→ * Multipart: Send ZIP as "file" field in multipart/form-data.
164→ * JSON: { zipPath: string } — for testing/CLI use.
165→ *
166→ * Returns: 201 with { imported, skipped, totalImported, totalSkipped }
167→ */
168→app.post('/import/claude-ai', async (c) => {
169→  const contentType = c.req.header('content-type') || '';
170→
171→  let zipBuffer: Buffer;
172→
173→  if (contentType.includes('multipart/form-data')) {
174→    const formData = await c.req.formData();
175→    const file = formData.get('file');
176→    if (!file || !(file instanceof File)) {
177→      return c.json({ error: 'No file uploaded. Send a ZIP file as "file" in multipart form data.' }, 400);
178→    }
179→    if (!file.name.endsWith('.zip')) {
180→      return c.json({ error: 'File must be a .zip file' }, 400);
181→    }
182→    const arrayBuffer = await file.arrayBuffer();
183→    if (arrayBuffer.byteLength > MAX_IMPORT_SIZE) {
184→      return c.json({ error: `File too large (${Math.round(arrayBuffer.byteLength / 1024 / 1024)}MB). Maximum is ${MAX_IMPORT_SIZE / 1024 / 1024}MB.` }, 400);
185→    }
186→    zipBuffer = Buffer.from(arrayBuffer);
187→  } else {
188→    const body = await c.req.json<{ zipPath: string }>();
189→    const { zipPath } = body;
190→    if (!zipPath || !zipPath.endsWith('.zip')) {
191→      return c.json({ error: 'File must be a .zip file' }, 400);
192→    }
193→    // Expand ~ and validate path
194→    const expandedZipPath = validateImportPath(expandHome(zipPath));
195→    if (!expandedZipPath) {
196→      return c.json({ error: 'Invalid file path' }, 400);
197→    }
198→    if (!fs.existsSync(expandedZipPath)) {
199→      return c.json({ error: 'File not found' }, 404);
200→    }
201→    const stat = fs.statSync(expandedZipPath);
202→    if (stat.size > MAX_IMPORT_SIZE) {
203→      return c.json({ error: `File too large (${Math.round(stat.size / 1024 / 1024)}MB). Maximum is ${MAX_IMPORT_SIZE / 1024 / 1024}MB.` }, 400);
204→    }
205→    zipBuffer = fs.readFileSync(expandedZipPath);
206→  }
207→
208→  // Extract conversations from ZIP
209→  let conversationFiles;
210→  try {
211→    conversationFiles = extractConversationsFromZip(zipBuffer);
212→  } catch {
213→    return c.json({ error: 'Invalid ZIP file' }, 400);
214→  }
215→
216→  if (conversationFiles.length === 0) {
217→    return c.json({ error: 'ZIP contains no conversations' }, 400);
218→  }
219→
220→  const imported: Array<{
221→    channelId: string;
222→    channelName: string;
223→    messageCount: number;
224→    artifactCount: number;
225→    conversationId: string;
226→  }> = [];
227→  const skipped: Array<{
228→    conversationId: string;
229→    reason: string;
230→    existingChannelId?: string;
231→  }> = [];
232→
233→  for (const { conversation } of conversationFiles) {
234→    const parsed = parseClaudeAiConversation(conversation);
235→
236→    if (parsed.turns.length === 0) {
237→      if (parsed.sessionId) {
238→        skipped.push({ conversationId: parsed.sessionId, reason: 'empty' });
239→      }
240→      continue;
241→    }
242→
243→    // Dedup check using the conversation UUID
244→    if (parsed.sessionId) {
245→      const existing = findChannelByOriginalSessionId(parsed.sessionId);
246→      if (existing) {
247→        skipped.push({
248→          conversationId: parsed.sessionId,
249→          reason: 'duplicate',
250→          existingChannelId: existing.id,
251→        });
252→        continue;
253→      }
254→    }
255→
256→    const conv = conversation as { uuid?: string; name?: string; created_at?: string; updated_at?: string };
257→
258→    const result = importSession({
259→      channelName: parsed.slug || `claude.ai — ${parsed.sessionId || 'import'}`,
260→      source: 'claude-ai',
261→      sourceMetadata: {
262→        originalSessionId: parsed.sessionId,
263→        conversationName: parsed.slug,
264→        createdAt: conv.created_at,
265→        updatedAt: conv.updated_at,
266→        eventCount: parsed.eventCount,
267→        importedAt: new Date().toISOString(),
268→      },
269→      turns: parsed.turns,
270→    });
271→
272→    imported.push({
273→      ...result,
274→      conversationId: parsed.sessionId || '',
275→    });
276→  }
277→
278→  // All duplicates → 409
279→  if (imported.length === 0 && skipped.every((s) => s.reason === 'duplicate')) {
280→    return c.json({
281→      error: 'All conversations already imported',
282→      imported: [],
283→      skipped,
284→      totalImported: 0,
285→      totalSkipped: skipped.length,
286→    }, 409);
287→  }
288→
289→  if (imported.length === 0) {
290→    return c.json({ error: 'No valid conversations found in ZIP' }, 400);
291→  }
292→
293→  return c.json({
294→    imported,
295→    skipped,
296→    totalImported: imported.length,
297→    totalSkipped: skipped.length,
298→  }, 201);
299→});
300→
301→export const importRoutes = app;
