  1→/**
  2→ * Claude Code JSONL Session Parser
  3→ *
  4→ * Parses Claude Code session files (~/.claude/projects/<path>/<session>.jsonl)
  5→ * into a structured format suitable for import into Klatch channels.
  6→ *
  7→ * Key design decisions:
  8→ * - Store everything, display selectively (full fidelity in DB, collapsed in UI)
  9→ * - Skip progress, file-history-snapshot, queue-operation events
 10→ * - Skip prompt_suggestion subagent events entirely
 11→ * - Extract compaction summaries from acompact-* subagent events
 12→ * - Group by turns: each human-typed user message starts a new turn (not parentUuid=null)
 13→ */
 14→
 15→import { createReadStream } from 'fs';
 16→import { createInterface } from 'readline';
 17→import path from 'path';
 18→import fs from 'fs';
 19→
 20→// ── Raw JSONL event types ─────────────────────────────────────
 21→
 22→export interface RawContentBlock {
 23→  type: 'text' | 'tool_use' | 'tool_result' | 'thinking' | 'image';
 24→  // text block
 25→  text?: string;
 26→  // tool_use block
 27→  id?: string;
 28→  name?: string;
 29→  input?: Record<string, any>;
 30→  // tool_result block
 31→  tool_use_id?: string;
 32→  content?: string;
 33→  is_error?: boolean;
 34→  // image block
 35→  source?: { type: string; media_type: string; data: string };
 36→  // thinking block
 37→  thinking?: string;
 38→}
 39→
 40→export interface RawEvent {
 41→  type: string; // "user" | "assistant" | "system" | "progress" | "file-history-snapshot" | "queue-operation"
 42→  uuid: string;
 43→  parentUuid: string | null;
 44→  sessionId?: string;
 45→  timestamp: string;
 46→  isSidechain?: boolean;
 47→  agentId?: string;
 48→  slug?: string;
 49→  cwd?: string;
 50→  version?: string;
 51→  gitBranch?: string;
 52→  message?: {
 53→    role: 'user' | 'assistant';
 54→    content: string | RawContentBlock[];
 55→    model?: string;
 56→    id?: string;
 57→    stop_reason?: string | null;
 58→    usage?: {
 59→      input_tokens?: number;
 60→      output_tokens?: number;
 61→    };
 62→  };
 63→  toolUseResult?: string;
 64→  // Injection metadata — see docs/JSONL-SCHEMA.md for full taxonomy
 65→  isMeta?: boolean;                  // true for hook feedback, skill injections, image references
 66→  isCompactSummary?: boolean;        // true for compaction context injections
 67→  isVisibleInTranscriptOnly?: boolean; // also true for compaction summaries
 68→  permissionMode?: string;           // "default" | "acceptEdits" — present on real human messages
 69→  sourceToolAssistantUUID?: string;  // present on tool results
 70→  sourceToolUseID?: string;          // present on skill/command injections
 71→  // System event fields
 72→  subtype?: string;                  // "compact_boundary" | "stop_hook_summary" | "api_error"
 73→  compactMetadata?: { trigger?: string; preTokens?: number };
 74→  logicalParentUuid?: string;        // preserves chain identity across compaction boundaries
 75→}
 76→
 77→// ── Parsed output types ───────────────────────────────────────
 78→
 79→export interface ParsedArtifact {
 80→  type: string;         // 'tool_use' | 'tool_result' | 'thinking' | 'image'
 81→  toolName: string;     // tool name (e.g., "Read", "Bash") or type label for non-tool
 82→  inputSummary: string; // human-readable summary (e.g., "src/App.tsx")
 83→  content?: string;     // full JSON or text content for DB storage
 84→}
 85→
 86→export interface ParsedTurn {
 87→  userText: string;
 88→  assistantText: string;
 89→  timestamp: string;        // ISO timestamp of the root user event
 90→  originalId: string;       // uuid of root user event
 91→  model?: string;           // model used for assistant response
 92→  artifacts?: ParsedArtifact[];
 93→}
 94→
 95→export interface ParsedSession {
 96→  sessionId?: string;
 97→  cwd?: string;
 98→  gitBranch?: string;
 99→  slug?: string;
100→  version?: string;
101→  model?: string;            // most commonly used model
102→  turns: ParsedTurn[];
103→  compactionSummary?: string; // from acompact-* subagent events
104→  eventCount: number;
105→  skippedLines?: number;     // malformed JSONL lines that were skipped
106→  firstTimestamp?: string;
107→  lastTimestamp?: string;
108→}
109→
110→// ── Event classification ──────────────────────────────────────
111→
112→/**
113→ * Keep only user/assistant events that are part of the main conversation.
114→ * Skip: progress, file-history-snapshot, queue-operation, system events.
115→ */
116→export function isConversationEvent(event: RawEvent): boolean {
117→  if (event.type !== 'user' && event.type !== 'assistant') return false;
118→  if (!event.message) return false;
119→  // Skip sidechain events (subagent conversations)
120→  if (event.isSidechain) return false;
121→  return true;
122→}
123→
124→/**
125→ * Classify a subagent by its agentId pattern.
126→ * - "acompact-*" -> compaction (context summarization)
127→ * - "aprompt_suggestion-*" -> prompt suggestion (skip entirely)
128→ * - "a{hex}" -> task subagent (store metadata)
129→ */
130→export function classifySubagent(agentId: string): 'task' | 'compact' | 'prompt_suggestion' {
131→  if (agentId.startsWith('acompact-')) return 'compact';
132→  if (agentId.startsWith('aprompt_suggestion-')) return 'prompt_suggestion';
133→  return 'task';
134→}
135→
136→// ── Content extraction ────────────────────────────────────────
137→
138→/**
139→ * Extract plain text from message content.
140→ * Handles both string content (simple user messages) and array content
141→ * (messages with mixed text/tool_use/tool_result/thinking blocks).
142→ */
143→export function extractTextContent(content: string | RawContentBlock[]): string {
144→  if (typeof content === 'string') return content;
145→  if (!Array.isArray(content)) return '';
146→
147→  const textParts: string[] = [];
148→  for (const block of content) {
149→    if (block.type === 'text' && block.text) {
150→      textParts.push(block.text);
151→    }
152→  }
153→  return textParts.join('\n\n');
154→}
155→
156→/**
157→ * Create a short input summary for a tool_use block.
158→ * Returns just the key detail (e.g., "src/App.tsx" for Read, "npm test" for Bash).
159→ */
160→export function summarizeToolInput(block: RawContentBlock): string {
161→  const input = block.input || {};
162→
163→  if (block.name === 'Read' && input.file_path) return shortenPath(input.file_path);
164→  if (block.name === 'Write' && input.file_path) return shortenPath(input.file_path);
165→  if (block.name === 'Edit' && input.file_path) return shortenPath(input.file_path);
166→  if (block.name === 'Bash' && input.command) {
167→    const cmd = String(input.command).slice(0, 60);
168→    return cmd + (String(input.command).length > 60 ? '...' : '');
169→  }
170→  if (block.name === 'Glob' && input.pattern) return String(input.pattern);
171→  if (block.name === 'Grep' && input.pattern) return String(input.pattern);
172→  if (block.name === 'Agent' && input.prompt) {
173→    const prompt = String(input.prompt).slice(0, 50);
174→    return prompt + (String(input.prompt).length > 50 ? '...' : '');
175→  }
176→  if (block.name === 'WebSearch' && input.query) return String(input.query);
177→  if (block.name === 'WebFetch' && input.url) return String(input.url);
178→  if (block.name === 'NotebookEdit' && input.notebook_path) return shortenPath(input.notebook_path);
179→
180→  // Generic: stringify first input key's value
181→  const keys = Object.keys(input);
182→  if (keys.length > 0) {
183→    const val = String(input[keys[0]]).slice(0, 40);
184→    return val;
185→  }
186→  return '';
187→}
188→
189→/** Shorten a file path to just the last 2 components */
190→function shortenPath(filePath: string): string {
191→  const parts = filePath.split('/');
192→  if (parts.length <= 2) return filePath;
193→  return parts.slice(-2).join('/');
194→}
195→
196→// ── Artifact extraction ───────────────────────────────────────
197→
198→/**
199→ * Extract tool_use artifacts from a message's content array.
200→ */
201→export function extractToolArtifacts(content: string | RawContentBlock[]): ParsedArtifact[] {
202→  if (typeof content === 'string') return [];
203→  if (!Array.isArray(content)) return [];
204→
205→  const artifacts: ParsedArtifact[] = [];
206→
207→  for (const block of content) {
208→    if (block.type === 'tool_use' && block.name) {
209→      artifacts.push({
210→        type: 'tool_use',
211→        toolName: block.name,
212→        inputSummary: summarizeToolInput(block),
213→        content: JSON.stringify({ name: block.name, input: block.input, id: block.id }),
214→      });
215→    }
216→  }
217→
218→  return artifacts;
219→}
220→
221→// ── Compaction summary extraction ─────────────────────────────
222→
223→/**
224→ * Extract the <summary> text from compaction subagent events.
225→ * Looks for assistant messages from acompact-* agents with <summary> tags.
226→ */
227→function extractCompactionFromEvents(events: RawEvent[]): string | undefined {
228→  for (const event of events) {
229→    // Only look at sidechain assistant events from compaction agents
230→    if (!event.isSidechain) continue;
231→    if (!event.agentId || !event.agentId.startsWith('acompact-')) continue;
232→    if (event.type !== 'assistant' || !event.message?.content) continue;
233→
234→    const text = extractTextContent(event.message.content);
235→    const match = text.match(/<summary>([\s\S]*?)<\/summary>/);
236→    if (match) return match[1].trim();
237→  }
238→  return undefined;
239→}
240→
241→// ── Turn boundary detection ───────────────────────────────────
242→
243→/**
244→ * Detect whether a user event is a real human-typed message (turn boundary)
245→ * vs. a system-injected event (tool_result, compaction summary, hook feedback, etc.).
246→ *
247→ * Uses the JSONL metadata fields to distinguish real human messages from injections.
248→ * See docs/JSONL-SCHEMA.md for the full taxonomy of user event subtypes.
249→ *
250→ * Real human messages: have text content, no injection flags.
251→ * Compaction summaries: isCompactSummary=true (render as system banner, not "You")
252→ * Hook/skill/image injections: isMeta=true
253→ * Tool results: content is array of tool_result blocks (no text blocks)
254→ */
255→export function isHumanTurnBoundary(event: RawEvent): boolean {
256→  if (event.type !== 'user') return false;
257→  if (event.message?.role !== 'user') return false;
258→
259→  // Filter out system-injected user messages using metadata flags
260→  if (event.isCompactSummary) return false;  // Compaction context injection
261→  if (event.isMeta) return false;             // Hook feedback, skill injection, image reference
262→
263→  const content = event.message.content;
264→  if (!content) return false;
265→
266→  // String content = human-typed message
267→  if (typeof content === 'string') return content.trim().length > 0;
268→
269→  // Array content: check for at least one text block with content
270→  // (tool_result arrays have no text blocks)
271→  if (Array.isArray(content)) {
272→    return content.some(
273→      (block) => block.type === 'text' && block.text && block.text.trim().length > 0
274→    );
275→  }
276→
277→  return false;
278→}
279→
280→// ── Turn grouping ─────────────────────────────────────────────
281→
282→/**
283→ * Group conversation events into user/assistant turn pairs.
284→ *
285→ * Turn boundaries are detected by finding user events with actual text
286→ * content (human-typed messages), not by parentUuid=null. In real Claude
287→ * Code sessions, only the very first event has parentUuid=null — subsequent
288→ * human messages chain from the previous assistant's response.
289→ *
290→ * Within a turn, we collect:
291→ * - User text content -> userText
292→ * - All assistant text content -> assistantText
293→ * - All tool_use blocks -> artifacts
294→ */
295→export function groupIntoTurns(events: RawEvent[]): ParsedTurn[] {
296→  // Sort by timestamp to ensure chronological order
297→  const sorted = [...events].sort((a, b) =>
298→    a.timestamp.localeCompare(b.timestamp)
299→  );
300→
301→  // Find turn boundary indices (human-typed user messages)
302→  const boundaryIndices: number[] = [];
303→  for (let i = 0; i < sorted.length; i++) {
304→    if (isHumanTurnBoundary(sorted[i])) {
305→      boundaryIndices.push(i);
306→    }
307→  }
308→
309→  const turns: ParsedTurn[] = [];
310→
311→  for (let b = 0; b < boundaryIndices.length; b++) {
312→    const startIdx = boundaryIndices[b];
313→    const endIdx = b + 1 < boundaryIndices.length
314→      ? boundaryIndices[b + 1]
315→      : sorted.length;
316→
317→    const turnRoot = sorted[startIdx];
318→    const turnEvents = sorted.slice(startIdx, endIdx);
319→
320→    // User text from the boundary event
321→    const userText = extractTextContent(turnRoot.message!.content);
322→
323→    // Collect assistant text and artifacts from events in this turn
324→    const assistantTextParts: string[] = [];
325→    const artifacts: ParsedArtifact[] = [];
326→    let model: string | undefined;
327→
328→    for (const event of turnEvents) {
329→      if (event.message?.role !== 'assistant') continue;
330→      if (!event.message.content) continue;
331→
332→      const text = extractTextContent(event.message.content);
333→      if (text.trim()) assistantTextParts.push(text);
334→
335→      // Extract tool artifacts from assistant messages
336→      artifacts.push(...extractToolArtifacts(event.message.content));
337→
338→      // Track model
339→      if (event.message.model && !model) {
340→        model = event.message.model;
341→      }
342→    }
343→
344→    const assistantText = assistantTextParts.join('\n\n');
345→
346→    turns.push({
347→      userText: userText || '',
348→      assistantText: assistantText || '',
349→      timestamp: turnRoot.timestamp,
350→      originalId: turnRoot.uuid,
351→      model,
352→      artifacts: artifacts.length > 0 ? artifacts : undefined,
353→    });
354→  }
355→
356→  return turns;
357→}
358→
359→// ── Main parse function (pure, for testability) ───────────────
360→
361→/**
362→ * Parse an array of raw JSONL events into a structured session.
363→ * This is the main pure function — no I/O, fully testable.
364→ */
365→export function parseEvents(events: unknown[]): ParsedSession {
366→  // Cast to RawEvent[] (events may come from JSON.parse which returns unknown)
367→  const rawEvents = events as RawEvent[];
368→
369→  if (rawEvents.length === 0) {
370→    return {
371→      sessionId: undefined,
372→      turns: [],
373→      eventCount: 0,
374→    };
375→  }
376→
377→  // Extract compaction summary from sidechain events (before filtering)
378→  const compactionSummary = extractCompactionFromEvents(rawEvents);
379→
380→  // Filter to conversation events only (skip progress, file-history-snapshot, sidechains, etc.)
381→  const conversationEvents = rawEvents.filter(isConversationEvent);
382→
383→  // Extract metadata: scan for the first event with each field
384→  // (queue-operation events lack cwd/gitBranch/slug/version)
385→  const first = rawEvents[0];
386→  const sessionId = first.sessionId;
387→  const metaEvent = rawEvents.find(e => e.cwd) || first;
388→  const cwd = metaEvent.cwd;
389→  const gitBranch = metaEvent.gitBranch;
390→  const slug = metaEvent.slug;
391→  const version = metaEvent.version;
392→
393→  // Find timestamps
394→  const timestamps = rawEvents
395→    .map(e => e.timestamp)
396→    .filter(Boolean)
397→    .sort();
398→  const firstTimestamp = timestamps[0];
399→  const lastTimestamp = timestamps[timestamps.length - 1];
400→
401→  // Group conversation events into turns
402→  const turns = groupIntoTurns(conversationEvents);
403→
404→  // Determine most common model
405→  const modelCounts = new Map<string, number>();
406→  for (const event of conversationEvents) {
407→    if (event.message?.model) {
408→      const m = event.message.model;
409→      modelCounts.set(m, (modelCounts.get(m) || 0) + 1);
410→    }
411→  }
412→  let model: string | undefined;
413→  let maxCount = 0;
414→  for (const [m, count] of modelCounts) {
415→    if (count > maxCount) {
416→      model = m;
417→      maxCount = count;
418→    }
419→  }
420→
421→  return {
422→    sessionId,
423→    cwd,
424→    gitBranch,
425→    slug,
426→    version,
427→    model,
428→    turns,
429→    compactionSummary,
430→    eventCount: rawEvents.length,
431→    firstTimestamp,
432→    lastTimestamp,
433→  };
434→}
435→
436→// ── File I/O (async, for the API layer) ───────────────────────
437→
438→export interface ReadJsonlResult {
439→  events: RawEvent[];
440→  skippedLines: number;
441→}
442→
443→/**
444→ * Read a JSONL file line-by-line and parse each line as JSON.
445→ * Skips malformed lines and reports how many were skipped.
446→ */
447→export async function readJsonlFile(filePath: string): Promise<ReadJsonlResult> {
448→  const events: RawEvent[] = [];
449→  let skippedLines = 0;
450→
451→  const stream = createReadStream(filePath, { encoding: 'utf-8' });
452→  const rl = createInterface({ input: stream, crlfDelay: Infinity });
453→
454→  for await (const line of rl) {
455→    const trimmed = line.trim();
456→    if (!trimmed) continue;
457→    try {
458→      events.push(JSON.parse(trimmed));
459→    } catch {
460→      skippedLines++;
461→    }
462→  }
463→
464→  return { events, skippedLines };
465→}
466→
467→/**
468→ * Scan for compaction subagent files and extract the latest summary.
469→ * Compaction subagents live at: <sessionDir>/subagents/agent-acompact-*.jsonl
470→ */
471→async function findCompactionSummary(sessionPath: string): Promise<string | undefined> {
472→  const sessionDir = path.dirname(sessionPath);
473→  const sessionId = path.basename(sessionPath, '.jsonl');
474→  const subagentDir = path.join(sessionDir, sessionId, 'subagents');
475→
476→  if (!fs.existsSync(subagentDir)) return undefined;
477→
478→  const files = fs.readdirSync(subagentDir)
479→    .filter(f => f.startsWith('agent-acompact-') && f.endsWith('.jsonl'))
480→    .sort();
481→
482→  // Try from latest to earliest
483→  for (let i = files.length - 1; i >= 0; i--) {
484→    const compactPath = path.join(subagentDir, files[i]);
485→    try {
486→      const { events } = await readJsonlFile(compactPath);
487→      const summary = extractCompactionFromEvents(events);
488→      if (summary) return summary;
489→    } catch {
490→      // Skip unreadable files
491→    }
492→  }
493→
494→  return undefined;
495→}
496→
497→/**
498→ * Main entry point: parse a Claude Code session from disk.
499→ *
500→ * @param sessionPath - Full path to the session .jsonl file
501→ * @returns ParsedSession with turns, artifacts, and metadata
502→ */
503→export async function parseClaudeCodeSession(sessionPath: string): Promise<ParsedSession> {
504→  const { events, skippedLines } = await readJsonlFile(sessionPath);
505→  const session = parseEvents(events);
506→  if (skippedLines > 0) {
507→    session.skippedLines = skippedLines;
508→  }
509→
510→  // Also try to find compaction summary from separate subagent files
511→  if (!session.compactionSummary) {
512→    const compactionSummary = await findCompactionSummary(sessionPath);
513→    if (compactionSummary) {
514→      session.compactionSummary = compactionSummary;
515→    }
516→  }
517→
518→  return session;
519→}
