  1→import Database from 'better-sqlite3';
  2→import path from 'path';
  3→import fs from 'fs';
  4→import { fileURLToPath } from 'url';
  5→import { DEFAULT_MODEL, DEFAULT_ENTITY_ID, ENTITY_COLORS, MODEL_ALIASES, DEFAULT_INTERACTION_MODE } from '@klatch/shared';
  6→
  7→const __dirname = path.dirname(fileURLToPath(import.meta.url));
  8→
  9→// Walk up to find the monorepo root (contains package.json with workspaces)
 10→function findProjectRoot(dir: string): string {
 11→  const pkg = path.join(dir, 'package.json');
 12→  if (fs.existsSync(pkg)) {
 13→    try {
 14→      const json = JSON.parse(fs.readFileSync(pkg, 'utf8'));
 15→      if (json.workspaces) return dir;
 16→    } catch { /* keep walking */ }
 17→  }
 18→  const parent = path.dirname(dir);
 19→  if (parent === dir) return process.cwd(); // fallback
 20→  return findProjectRoot(parent);
 21→}
 22→
 23→const DB_PATH = path.join(findProjectRoot(__dirname), 'klatch.db');
 24→
 25→let db: Database.Database;
 26→
 27→export function getDb(): Database.Database {
 28→  if (!db) {
 29→    db = new Database(DB_PATH);
 30→    db.pragma('journal_mode = WAL');
 31→    db.pragma('foreign_keys = ON');
 32→    initSchema();
 33→    runMigrations();
 34→  }
 35→  return db;
 36→}
 37→
 38→function initSchema() {
 39→  db.exec(`
 40→    CREATE TABLE IF NOT EXISTS channels (
 41→      id TEXT PRIMARY KEY,
 42→      name TEXT NOT NULL,
 43→      system_prompt TEXT NOT NULL DEFAULT '',
 44→      model TEXT NOT NULL DEFAULT '${DEFAULT_MODEL}',
 45→      mode TEXT NOT NULL DEFAULT '${DEFAULT_INTERACTION_MODE}',
 46→      created_at TEXT NOT NULL DEFAULT (datetime('now'))
 47→    );
 48→
 49→    CREATE TABLE IF NOT EXISTS messages (
 50→      id TEXT PRIMARY KEY,
 51→      channel_id TEXT NOT NULL REFERENCES channels(id),
 52→      role TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
 53→      content TEXT NOT NULL DEFAULT '',
 54→      status TEXT NOT NULL DEFAULT 'complete' CHECK (status IN ('complete', 'streaming', 'error')),
 55→      model TEXT,
 56→      created_at TEXT NOT NULL DEFAULT (datetime('now'))
 57→    );
 58→
 59→    CREATE TABLE IF NOT EXISTS entities (
 60→      id TEXT PRIMARY KEY,
 61→      name TEXT NOT NULL,
 62→      handle TEXT,
 63→      model TEXT NOT NULL DEFAULT '${DEFAULT_MODEL}',
 64→      system_prompt TEXT NOT NULL DEFAULT '',
 65→      color TEXT NOT NULL DEFAULT '${ENTITY_COLORS[0]}',
 66→      created_at TEXT NOT NULL DEFAULT (datetime('now'))
 67→    );
 68→
 69→    CREATE TABLE IF NOT EXISTS channel_entities (
 70→      channel_id TEXT NOT NULL REFERENCES channels(id),
 71→      entity_id TEXT NOT NULL REFERENCES entities(id),
 72→      added_at TEXT NOT NULL DEFAULT (datetime('now')),
 73→      PRIMARY KEY (channel_id, entity_id)
 74→    );
 75→
 76→    INSERT OR IGNORE INTO channels (id, name, system_prompt)
 77→    VALUES ('default', 'general', 'You are a helpful assistant.');
 78→
 79→    INSERT OR IGNORE INTO entities (id, name, model, system_prompt, color)
 80→    VALUES ('${DEFAULT_ENTITY_ID}', 'Claude', '${DEFAULT_MODEL}', 'You are a helpful assistant.', '${ENTITY_COLORS[0]}');
 81→  `);
 82→}
 83→
 84→function runMigrations() {
 85→  // Add model column to channels if it doesn't exist
 86→  const channelCols = db.prepare("PRAGMA table_info(channels)").all() as { name: string }[];
 87→  if (!channelCols.some((c) => c.name === 'model')) {
 88→    db.exec(`ALTER TABLE channels ADD COLUMN model TEXT NOT NULL DEFAULT '${DEFAULT_MODEL}'`);
 89→  }
 90→
 91→  // Add model column to messages if it doesn't exist
 92→  const msgCols = db.prepare("PRAGMA table_info(messages)").all() as { name: string }[];
 93→  if (!msgCols.some((c) => c.name === 'model')) {
 94→    db.exec(`ALTER TABLE messages ADD COLUMN model TEXT`);
 95→  }
 96→
 97→  // Add entity_id column to messages if it doesn't exist
 98→  if (!msgCols.some((c) => c.name === 'entity_id')) {
 99→    db.exec(`ALTER TABLE messages ADD COLUMN entity_id TEXT`);
100→  }
101→
102→  // Add mode column to channels if it doesn't exist
103→  if (!channelCols.some((c) => c.name === 'mode')) {
104→    db.exec(`ALTER TABLE channels ADD COLUMN mode TEXT NOT NULL DEFAULT '${DEFAULT_INTERACTION_MODE}'`);
105→  }
106→
107→  // Migrate legacy model IDs to current versions
108→  for (const [oldId, newId] of Object.entries(MODEL_ALIASES)) {
109→    db.prepare('UPDATE channels SET model = ? WHERE model = ?').run(newId, oldId);
110→    db.prepare('UPDATE messages SET model = ? WHERE model = ?').run(newId, oldId);
111→  }
112→
113→  // Add handle column to entities if it doesn't exist
114→  const entityCols = db.prepare("PRAGMA table_info(entities)").all() as { name: string }[];
115→  if (!entityCols.some((c) => c.name === 'handle')) {
116→    db.exec(`ALTER TABLE entities ADD COLUMN handle TEXT`);
117→  }
118→
119→  // ── Step 8: Import support ─────────────────────────────────
120→
121→  // Add source tracking columns to channels
122→  if (!channelCols.some((c) => c.name === 'source')) {
123→    db.exec(`ALTER TABLE channels ADD COLUMN source TEXT DEFAULT 'native'`);
124→  }
125→  if (!channelCols.some((c) => c.name === 'source_metadata')) {
126→    db.exec(`ALTER TABLE channels ADD COLUMN source_metadata TEXT`);
127→  }
128→
129→  // Add original IDs to messages for imported conversations
130→  // Re-read msgCols since we might have added columns above
131→  const msgCols2 = db.prepare("PRAGMA table_info(messages)").all() as { name: string }[];
132→  if (!msgCols2.some((c) => c.name === 'original_timestamp')) {
133→    db.exec(`ALTER TABLE messages ADD COLUMN original_timestamp TEXT`);
134→  }
135→  if (!msgCols2.some((c) => c.name === 'original_id')) {
136→    db.exec(`ALTER TABLE messages ADD COLUMN original_id TEXT`);
137→  }
138→
139→  // Create message_artifacts table for tool use, thinking, images from imports
140→  db.exec(`
141→    CREATE TABLE IF NOT EXISTS message_artifacts (
142→      id TEXT PRIMARY KEY,
143→      message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
144→      type TEXT NOT NULL,
145→      tool_name TEXT,
146→      input_summary TEXT,
147→      content TEXT,
148→      created_at TEXT NOT NULL DEFAULT (datetime('now'))
149→    );
150→    CREATE INDEX IF NOT EXISTS idx_message_artifacts_message_id ON message_artifacts(message_id);
151→  `);
152→
153→  // ── Phase 2: Compaction support ──────────────────────────────
154→
155→  // Add compaction_state to channels for storing API compaction summaries
156→  const channelCols3 = db.prepare("PRAGMA table_info(channels)").all() as { name: string }[];
157→  if (!channelCols3.some((c) => c.name === 'compaction_state')) {
158→    db.exec(`ALTER TABLE channels ADD COLUMN compaction_state TEXT`);
159→  }
160→
161→  // Ensure default entity exists (for existing databases being upgraded)
162→  const defaultEntity = db.prepare('SELECT id FROM entities WHERE id = ?').get(DEFAULT_ENTITY_ID);
163→  if (!defaultEntity) {
164→    db.prepare(
165→      'INSERT INTO entities (id, name, model, system_prompt, color) VALUES (?, ?, ?, ?, ?)'
166→    ).run(DEFAULT_ENTITY_ID, 'Claude', DEFAULT_MODEL, 'You are a helpful assistant.', ENTITY_COLORS[0]);
167→  }
168→
169→  // Auto-assign default entity to any channels that have no entities assigned
170→  const unassignedChannels = db.prepare(`
171→    SELECT c.id FROM channels c
172→    LEFT JOIN channel_entities ce ON c.id = ce.channel_id
173→    WHERE ce.channel_id IS NULL
174→  `).all() as { id: string }[];
175→
176→  for (const ch of unassignedChannels) {
177→    db.prepare(
178→      'INSERT OR IGNORE INTO channel_entities (channel_id, entity_id) VALUES (?, ?)'
179→    ).run(ch.id, DEFAULT_ENTITY_ID);
180→  }
181→}
