 73→export function getAllChannelsEnriched(): Channel[] {
 74→  const rows = getDb()
 75→    .prepare(`
 76→      SELECT c.*,
 77→        COUNT(DISTINCT ce.entity_id) as entity_count,
 78→        (SELECT COUNT(*) FROM messages m WHERE m.channel_id = c.id) as message_count,
 79→        (SELECT MAX(m.created_at) FROM messages m WHERE m.channel_id = c.id) as last_message_at
 80→      FROM channels c
