 94→/**
 95→ * Get detailed stats for a single channel: message count, artifact count,
 96→ * tool-use breakdown, and last activity timestamp.
 97→ */
 98→export function getChannelStats(channelId: string): ChannelStats | undefined {
 99→  const db = getDb();
100→
101→  // Verify channel exists
102→  const channel = db.prepare('SELECT id FROM channels WHERE id = ?').get(channelId);
103→  if (!channel) return undefined;
104→
105→  // Message count and last activity
106→  const counts = db.prepare(`
107→    SELECT COUNT(*) as message_count, MAX(created_at) as last_message_at
108→    FROM messages WHERE channel_id = ?
109→  `).get(channelId) as { message_count: number; last_message_at: string | null };
110→
111→  // Artifact count
112→  const artifactRow = db.prepare(`
113→    SELECT COUNT(*) as artifact_count
114→    FROM message_artifacts ma
115→    JOIN messages m ON ma.message_id = m.id
116→    WHERE m.channel_id = ?
117→  `).get(channelId) as { artifact_count: number };
118→
119→  // Tool breakdown (tool_use artifacts only, sorted by frequency)
120→  const toolRows = db.prepare(`
121→    SELECT ma.tool_name as tool, COUNT(*) as count
122→    FROM message_artifacts ma
123→    JOIN messages m ON ma.message_id = m.id
124→    WHERE m.channel_id = ? AND ma.type = 'tool_use' AND ma.tool_name IS NOT NULL
125→    GROUP BY ma.tool_name
126→    ORDER BY count DESC
127→  `).all(channelId) as { tool: string; count: number }[];
128→
129→  return {
130→    messageCount: counts.message_count,
131→    artifactCount: artifactRow.artifact_count,
132→    toolBreakdown: toolRows,
133→    lastMessageAt: counts.last_message_at,
134→  };
135→}
