137→export function createChannel(name: string, systemPrompt: string, model?: ModelId, mode?: InteractionMode): Channel {
138→  const db = getDb();
139→  const id = uuidv4();
140→  const now = new Date().toISOString();
141→  const channelModel = model || DEFAULT_MODEL;
142→  const channelMode = mode || DEFAULT_INTERACTION_MODE;
143→
144→  const txn = db.transaction(() => {
145→    db.prepare('INSERT INTO channels (id, name, system_prompt, model, mode, created_at) VALUES (?, ?, ?, ?, ?, ?)')
146→      .run(id, name, systemPrompt, channelModel, channelMode, now);
147→    // Auto-assign default entity to new channels
148→    db.prepare('INSERT INTO channel_entities (channel_id, entity_id) VALUES (?, ?)')
149→      .run(id, DEFAULT_ENTITY_ID);
150→  });
151→  txn();
152→
153→  return { id, name, systemPrompt, model: channelModel, mode: channelMode, createdAt: now, source: 'native' as ChannelSource };
154→}
