402→import type { ImportResult } from '@klatch/shared';
403→import type { ParsedTurn, ParsedArtifact } from '../import/parser.js';
404→
405→interface ImportSessionParams {
406→  channelName: string;
407→  source: 'claude-code' | 'claude-ai';
408→  sourceMetadata: Record<string, unknown>;
409→  model?: string;
410→  turns: ParsedTurn[];
411→}
412→
413→/**
414→ * Import a parsed session into the database as a new channel with messages and artifacts.
415→ * Runs in a single transaction for atomicity.
416→ */
417→export function importSession(params: ImportSessionParams): ImportResult {
418→  const db = getDb();
419→  const { channelName, source, sourceMetadata, model, turns } = params;
420→
421→  const channelId = uuidv4();
422→  const now = new Date().toISOString();
423→  const channelModel = model || DEFAULT_MODEL;
424→
425→  let messageCount = 0;
426→  let artifactCount = 0;
427→
428→  const txn = db.transaction(() => {
429→    // 1. Create channel with source info
430→    db.prepare(
431→      'INSERT INTO channels (id, name, system_prompt, model, mode, source, source_metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)'
432→    ).run(channelId, channelName, '', channelModel, DEFAULT_INTERACTION_MODE, source, JSON.stringify(sourceMetadata), now);
433→
434→    // 2. Assign default entity
435→    db.prepare(
436→      'INSERT INTO channel_entities (channel_id, entity_id) VALUES (?, ?)'
437→    ).run(channelId, DEFAULT_ENTITY_ID);
438→
439→    // 3. Insert messages from turns
440→    const insertMsg = db.prepare(
441→      'INSERT INTO messages (id, channel_id, role, content, status, model, entity_id, original_timestamp, original_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
442→    );
443→    const insertArtifact = db.prepare(
444→      'INSERT INTO message_artifacts (id, message_id, type, tool_name, input_summary, content, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)'
445→    );
446→
447→    for (const turn of turns) {
448→      // User message
449→      if (turn.userText) {
450→        const userMsgId = uuidv4();
451→        insertMsg.run(
452→          userMsgId, channelId, 'user', turn.userText, 'complete',
453→          null, null, turn.timestamp, turn.originalId, now
454→        );
455→        messageCount++;
456→      }
457→
458→      // Assistant message
459→      if (turn.assistantText || (turn.artifacts && turn.artifacts.length > 0)) {
460→        const assistantMsgId = uuidv4();
461→        insertMsg.run(
462→          assistantMsgId, channelId, 'assistant', turn.assistantText || '', 'complete',
463→          turn.model || channelModel, DEFAULT_ENTITY_ID, turn.timestamp, turn.originalId, now
464→        );
465→        messageCount++;
466→
467→        // Artifacts (tool uses)
468→        if (turn.artifacts) {
469→          for (const artifact of turn.artifacts) {
470→            insertArtifact.run(
471→              uuidv4(), assistantMsgId, artifact.type,
472→              artifact.toolName, artifact.inputSummary,
473→              artifact.content || null, now
474→            );
475→            artifactCount++;
476→          }
477→        }
478→      }
479→    }
480→  });
481→
482→  txn();
483→
484→  return {
485→    channelId,
486→    channelName,
487→    messageCount,
488→    artifactCount,
489→    source,
490→    duplicate: false,
491→  };
492→}
493→
494→/**
495→ * Find a channel that was imported from the same original session.
496→ * Uses json_extract on source_metadata to match originalSessionId.
497→ */
498→export function findChannelByOriginalSessionId(sessionId: string): Channel | undefined {
499→  const row = getDb()
500→    .prepare("SELECT * FROM channels WHERE json_extract(source_metadata, '$.originalSessionId') = ?")
501→    .get(sessionId) as any;
502→  if (!row) return undefined;
503→  return rowToChannel(row);
504→}
