  1→import Anthropic from '@anthropic-ai/sdk';
  2→import { EventEmitter } from 'events';
  3→import { getMessages, getChannel, updateMessage, updateChannelCompaction } from '../db/queries.js';
  4→import type { Entity, Channel } from '@klatch/shared';
  5→import { DEFAULT_MODEL } from '@klatch/shared';
  6→
  7→// Lazy-init: the Anthropic client must not be created at import time
  8→// because ESM hoists imports before dotenv.config() runs in index.ts.
  9→let _anthropic: Anthropic | null = null;
 10→function getAnthropicClient(): Anthropic {
 11→  if (!_anthropic) {
 12→    _anthropic = new Anthropic();
 13→  }
 14→  return _anthropic;
 15→}
 16→
 17→// In-memory registry of active streams
 18→export const activeStreams = new Map<string, EventEmitter>();
 19→
 20→// Store the Anthropic stream objects so we can abort them
 21→// Using `any` to accommodate both regular and beta stream types
 22→const activeAnthropicStreams = new Map<string, { abort(): void }>();
 23→
 24→// Track active roundtable sessions so we can cancel remaining entities on abort
 25→// Maps channelId → Set of assistant message IDs in the current round
 26→const activeRoundtables = new Map<string, { messageIds: string[]; cancelled: boolean }>();
 27→
 28→export function abortStream(messageId: string): boolean {
 29→  const stream = activeAnthropicStreams.get(messageId);
 30→  if (stream) {
 31→    stream.abort();
 32→  }
 33→
 34→  // If this message belongs to a roundtable, cancel the whole round
 35→  for (const [, roundtable] of activeRoundtables) {
 36→    if (roundtable.messageIds.includes(messageId)) {
 37→      roundtable.cancelled = true;
 38→      // Mark any not-yet-started placeholders as complete (empty)
 39→      for (const id of roundtable.messageIds) {
 40→        if (id !== messageId && !activeAnthropicStreams.has(id)) {
 41→          // This entity hasn't started yet — clean up its placeholder
 42→          const emitter = activeStreams.get(id);
 43→          if (emitter) {
 44→            updateMessage(id, '', 'complete');
 45→            emitter.emit('data', {
 46→              type: 'message_complete',
 47→              messageId: id,
 48→              content: '',
 49→            });
 50→            activeStreams.delete(id);
 51→          } else {
 52→            // No emitter yet (hasn't been created) — just mark DB
 53→            updateMessage(id, '', 'complete');
 54→          }
 55→        }
 56→      }
 57→      break;
 58→    }
 59→  }
 60→
 61→  return !!stream;
 62→}
 63→
 64→// ── History builders ──────────────────────────────────────────
 65→
 66→type ChatMessage = { role: 'user' | 'assistant'; content: string };
 67→
 68→// Safety cap: prevents token overflow for long imported sessions.
 69→// When compaction state exists, the cap is bypassed (compaction manages length).
 70→const MAX_HISTORY_MESSAGES = 200;
 71→
 72→/** Parsed compaction state from channel JSON */
 73→interface CompactionState {
 74→  summary: string;
 75→  timestamp: string;
 76→  beforeMessageId: string;
 77→}
 78→
 79→function parseCompactionState(channel?: Channel): CompactionState | null {
 80→  if (!channel?.compactionState) return null;
 81→  try {
 82→    return JSON.parse(channel.compactionState);
 83→  } catch {
 84→    return null;
 85→  }
 86→}
 87→
 88→/**
 89→ * Merge consecutive same-role messages into one.
 90→ * The Anthropic API requires strict user/assistant alternation.
 91→ * This can happen after filtering (panel mode removes other entities' messages)
 92→ * or in roundtable mode (multiple assistant responses per round).
 93→ */
 94→function coalesceMessages(messages: ChatMessage[]): ChatMessage[] {
 95→  if (messages.length === 0) return messages;
 96→  const result: ChatMessage[] = [messages[0]];
 97→  for (let i = 1; i < messages.length; i++) {
 98→    const prev = result[result.length - 1];
 99→    if (messages[i].role === prev.role) {
100→      prev.content += '\n\n' + messages[i].content;
101→    } else {
102→      result.push({ ...messages[i] });
103→    }
104→  }
105→  return result;
106→}
107→
108→/** Panel mode: entity sees only its own past responses + all user messages */
109→function buildPanelHistory(channelId: string, entity: Entity): ChatMessage[] {
110→  const channel = getChannel(channelId);
111→  const compaction = parseCompactionState(channel);
112→  const allMessages = getMessages(channelId).filter((m) => m.status === 'complete');
113→
114→  let messages = allMessages;
115→
116→  if (compaction) {
117→    // Find the boundary message and only include messages after it
118→    const boundaryIdx = messages.findIndex((m) => m.id === compaction.beforeMessageId);
119→    if (boundaryIdx >= 0) {
120→      messages = messages.slice(boundaryIdx + 1);
121→    }
122→  }
123→
124→  const filtered = messages
125→    .filter((m) => m.role === 'user' || m.entityId === entity.id || !m.entityId)
126→    .filter((m) => m.content.trim().length > 0)
127→    .map((m) => ({ role: m.role as 'user' | 'assistant', content: m.content }));
128→
129→  if (compaction) {
130→    // Prepend compaction summary as conversation anchor
131→    // coalesceMessages handles the case where first filtered message is also 'user'
132→    return coalesceMessages([{ role: 'user' as const, content: compaction.summary }, ...filtered]);
133→  }
134→
135→  // No compaction: apply safety cap
136→  return coalesceMessages(filtered.slice(-MAX_HISTORY_MESSAGES));
137→}
138→
139→/** Roundtable mode: entity sees ALL completed messages from ALL entities */
140→function buildRoundtableHistory(channelId: string): ChatMessage[] {
141→  const channel = getChannel(channelId);
142→  const compaction = parseCompactionState(channel);
143→  const allMessages = getMessages(channelId).filter((m) => m.status === 'complete');
144→
145→  let messages = allMessages;
146→
147→  if (compaction) {
148→    const boundaryIdx = messages.findIndex((m) => m.id === compaction.beforeMessageId);
149→    if (boundaryIdx >= 0) {
150→      messages = messages.slice(boundaryIdx + 1);
151→    }
152→  }
153→
154→  const filtered = messages
155→    .filter((m) => m.content.trim().length > 0)
156→    .map((m) => ({
157→      role: m.role as 'user' | 'assistant',
158→      content: m.content,
159→    }));
160→
161→  if (compaction) {
162→    return coalesceMessages([{ role: 'user' as const, content: compaction.summary }, ...filtered]);
163→  }
164→
165→  return coalesceMessages(filtered.slice(-MAX_HISTORY_MESSAGES));
166→}
167→
168→/** Build system prompt: channel preamble + entity's own prompt */
169→function buildSystemPrompt(entity: Entity, channelPreamble?: string): string {
170→  const parts: string[] = [];
171→  if (channelPreamble?.trim()) parts.push(channelPreamble.trim());
172→  if (entity.systemPrompt?.trim()) parts.push(entity.systemPrompt.trim());
173→  return parts.join('\n\n');
174→}
