176→// ── Core streaming function ──────────────────────────────────
177→
178→interface StreamResult {
179→  content: string;
180→  compactionSummary?: string;
181→}
182→
183→/**
184→ * Stream a Claude response. Used by both panel and roundtable modes.
185→ * Uses the beta API when compaction is enabled to support context_management.
186→ *
187→ * @returns StreamResult with content and optional compaction summary
188→ */
189→async function streamClaudeCore(
190→  assistantMessageId: string,
191→  entity: Entity,
192→  history: ChatMessage[],
193→  systemPrompt: string,
194→  options?: { compactionEnabled?: boolean }
195→): Promise<StreamResult> {
196→  const emitter = new EventEmitter();
197→  activeStreams.set(assistantMessageId, emitter);
198→
199→  let fullContent = '';
200→  let compactionSummary: string | undefined;
201→
202→  try {
203→    const model = entity.model || DEFAULT_MODEL;
204→
205→    if (options?.compactionEnabled) {
206→      // Use beta API with compaction support
207→      const stream = getAnthropicClient().beta.messages.stream({
208→        model,
209→        max_tokens: 4096,
210→        system: systemPrompt || undefined,
211→        messages: history,
212→        betas: ['compact-2026-01-12'],
213→        context_management: {
214→          edits: [{
215→            type: 'compact_20260112',
216→            trigger: { type: 'input_tokens', value: 80000 },
217→          }],
218→        },
219→      });
220→
221→      activeAnthropicStreams.set(assistantMessageId, stream);
222→
223→      stream.on('text', (text) => {
224→        fullContent += text;
225→        emitter.emit('data', {
226→          type: 'text_delta',
227→          messageId: assistantMessageId,
228→          content: text,
229→        });
230→      });
231→
232→      stream.on('compaction', (compactedContent) => {
233→        compactionSummary = compactedContent;
234→      });
235→
236→      await stream.finalMessage();
237→    } else {
238→      // Standard API (no compaction)
239→      const stream = getAnthropicClient().messages.stream({
240→        model,
241→        max_tokens: 4096,
242→        system: systemPrompt || undefined,
243→        messages: history,
244→      });
245→
246→      activeAnthropicStreams.set(assistantMessageId, stream);
247→
248→      stream.on('text', (text) => {
249→        fullContent += text;
250→        emitter.emit('data', {
251→          type: 'text_delta',
252→          messageId: assistantMessageId,
253→          content: text,
254→        });
255→      });
256→
257→      await stream.finalMessage();
258→    }
259→
260→    updateMessage(assistantMessageId, fullContent, 'complete');
261→    emitter.emit('data', {
262→      type: 'message_complete',
263→      messageId: assistantMessageId,
264→      content: fullContent,
265→    });
266→  } catch (err) {
267→    // Check if this was an intentional abort
268→    if (err instanceof Anthropic.APIUserAbortError || (err instanceof Error && err.name === 'AbortError')) {
269→      // Abort: keep partial content, mark as complete
270→      updateMessage(assistantMessageId, fullContent, 'complete');
271→      emitter.emit('data', {
272→        type: 'message_complete',
273→        messageId: assistantMessageId,
274→        content: fullContent,
275→      });
276→    } else {
277→      let errorMsg: string;
278→      if (err instanceof Anthropic.AuthenticationError) {
279→        errorMsg = 'Invalid API key. Set ANTHROPIC_API_KEY in .env and restart the server.';
280→      } else if (err instanceof Anthropic.APIError) {
281→        errorMsg = `API error (${err.status}): ${err.message}`;
282→      } else {
283→        errorMsg = err instanceof Error ? err.message : String(err);
284→      }
285→      updateMessage(assistantMessageId, fullContent || errorMsg, 'error');
286→      emitter.emit('data', {
287→        type: 'error',
288→        messageId: assistantMessageId,
289→        content: errorMsg,
290→      });
291→    }
292→  } finally {
293→    activeAnthropicStreams.delete(assistantMessageId);
294→    activeStreams.delete(assistantMessageId);
295→  }
296→
297→  return { content: fullContent, compactionSummary };
298→}
299→
300→// ── Public API ───────────────────────────────────────────────
301→
302→/**
303→ * Panel mode: stream a single entity's response in isolation.
304→ * Each entity sees only its own history + user messages.
305→ * Fire-and-forget (don't await) — streams in parallel.
306→ */
307→export async function streamClaude(
308→  channelId: string,
309→  assistantMessageId: string,
310→  entity: Entity,
311→  channelPreamble?: string
312→) {
313→  const channel = getChannel(channelId);
314→  const compactionEnabled = channel?.source !== 'native';
315→  const history = buildPanelHistory(channelId, entity);
316→  const systemPrompt = buildSystemPrompt(entity, channelPreamble);
317→  const result = await streamClaudeCore(
318→    assistantMessageId, entity, history, systemPrompt,
319→    { compactionEnabled }
320→  );
321→
322→  // Store compaction result if the API compacted
323→  if (result.compactionSummary && channel) {
324→    // Find the last user message before the one that triggered this stream
325→    const messages = getMessages(channelId).filter((m) => m.status === 'complete' && m.role === 'user');
326→    const lastUserMsg = messages[messages.length - 1];
327→    if (lastUserMsg) {
328→      updateChannelCompaction(channelId, {
329→        summary: result.compactionSummary,
330→        timestamp: new Date().toISOString(),
331→        beforeMessageId: lastUserMsg.id,
332→      });
333→    }
334→  }
335→}
336→
337→/**
338→ * Roundtable mode: stream entities sequentially, each seeing prior responses.
339→ * This is an async orchestrator — it awaits each stream before starting the next.
340→ *
341→ * The Anthropic API requires conversations to end with a user message.
342→ * For Entity 2+, we present prior entities' responses from the current round
343→ * as context in a synthetic user message, so each entity knows what others said.
344→ *
345→ * @param channelId — channel for history lookup
346→ * @param assistants — ordered list of { messageId, entity } to stream
347→ * @param channelPreamble — shared channel system prompt
348→ * @param allEntities — full list of entities for name lookup in context messages
349→ */
350→export async function streamClaudeRoundtable(
351→  channelId: string,
352→  assistants: { assistantMessageId: string; entity: Entity }[],
353→  channelPreamble?: string
354→) {
355→  const channel = getChannel(channelId);
356→  const compactionEnabled = channel?.source !== 'native';
357→
358→  // Register this roundtable so abort can cancel the whole round
359→  const roundtable = {
360→    messageIds: assistants.map((a) => a.assistantMessageId),
361→    cancelled: false,
362→  };
363→  activeRoundtables.set(channelId, roundtable);
364→
365→  try {
366→    // Start with the shared history (all completed messages in the channel)
367→    const baseHistory = buildRoundtableHistory(channelId);
368→
369→    // Track responses from the current round
370→    const roundResponses: { entity: Entity; content: string }[] = [];
371→
372→    for (let i = 0; i < assistants.length; i++) {
373→      // Check if the round was cancelled (e.g. user hit Stop on an earlier entity)
374→      if (roundtable.cancelled) break;
375→
376→      const { assistantMessageId, entity } = assistants[i];
377→      const systemPrompt = buildSystemPrompt(entity, channelPreamble);
378→
379→      let history: ChatMessage[];
380→
381→      if (i === 0) {
382→        // First entity: normal history (ends with user message)
383→        history = baseHistory;
384→      } else {
385→        // Subsequent entities: base history + a synthetic user message
386→        // containing prior entities' responses as context
387→        const priorContext = roundResponses
388→          .map((r) => `[${r.entity.name} responded]: ${r.content}`)
389→          .join('\n\n');
390→
391→        history = [
392→          ...baseHistory,
393→          {
394→            role: 'user' as const,
395→            content: `The following responses have been given by other participants in this roundtable discussion:\n\n${priorContext}\n\nNow it's your turn to respond to the original message.`,
396→          },
397→        ];
398→      }
399→
400→      // Only enable compaction for the first entity in a round
401→      // (subsequent entities get synthetic context, compaction would be confusing)
402→      const result = await streamClaudeCore(
403→        assistantMessageId,
404→        entity,
405→        history,
406→        systemPrompt,
407→        { compactionEnabled: i === 0 && compactionEnabled }
408→      );
409→
410→      // Store compaction if it happened on the first entity
411→      if (result.compactionSummary && channel) {
412→        const messages = getMessages(channelId).filter((m) => m.status === 'complete' && m.role === 'user');
413→        const lastUserMsg = messages[messages.length - 1];
414→        if (lastUserMsg) {
415→          updateChannelCompaction(channelId, {
416→            summary: result.compactionSummary,
417→            timestamp: new Date().toISOString(),
418→            beforeMessageId: lastUserMsg.id,
419→          });
420→        }
421→      }
422→
423→      roundResponses.push({ entity, content: result.content });
424→    }
425→  } finally {
426→    activeRoundtables.delete(channelId);
427→  }
428→}
