130→// ── @-mention parsing for directed mode ──────────────────────
131→
132→/**
133→ * Extract @-mentioned entity names from message content.
134→ * Matches `@EntityName` at word boundaries. Entity names may contain
135→ * letters, numbers, hyphens, underscores, and spaces (when quoted).
136→ *
137→ * Supported formats:
138→ *   @Claude       → "Claude"
139→ *   @code-reviewer → "code-reviewer"
140→ *   @"Chief of Staff" → "Chief of Staff"
141→ *
142→ * Returns an array of mentioned names (lowercased for matching).
143→ */
144→export function parseMentions(content: string): string[] {
145→  const mentions: string[] = [];
146→
147→  // Match @"quoted name" or @word-with-hyphens_and_numbers
148→  const regex = /@"([^"]+)"|@([\w][\w-]*)/g;
149→  let match;
150→  while ((match = regex.exec(content)) !== null) {
151→    const name = match[1] || match[2]; // quoted group or unquoted group
152→    if (name) mentions.push(name.toLowerCase());
153→  }
154→
155→  return [...new Set(mentions)]; // deduplicate
156→}
157→
158→/**
159→ * Resolve mentioned names to entities. Case-insensitive matching
160→ * against both entity name and optional handle (slug).
161→ * Returns the matched entities in the order they appear in the entities list.
162→ */
163→export function resolveMentions(content: string, entities: Entity[]): Entity[] {
164→  const mentionedNames = parseMentions(content);
165→  if (mentionedNames.length === 0) return [];
166→
167→  return entities.filter((e) =>
168→    mentionedNames.includes(e.name.toLowerCase()) ||
169→    (e.handle && mentionedNames.includes(e.handle.toLowerCase()))
170→  );
171→}
