 28→
 29→// Send a message — creates user msg + N assistant placeholders (one per entity), kicks off N streams
 30→app.post('/channels/:channelId/messages', async (c) => {
 31→  const channelId = c.req.param('channelId');
 32→  const { content } = await c.req.json<{ content: string }>();
 33→
 34→  // Input validation
 35→  if (!content?.trim()) {
 36→    return c.json({ error: 'Message content is required' }, 400);
 37→  }
 38→
 39→  // Channel existence check
 40→  const channel = getChannel(channelId);
 41→  if (!channel) {
 42→    return c.json({ error: 'Channel not found' }, 404);
 43→  }
 44→
 45→  // Get assigned entities
 46→  const entities = getChannelEntities(channelId);
 47→  if (entities.length === 0) {
 48→    return c.json({ error: 'No entities assigned to this channel' }, 400);
 49→  }
 50→
 51→  // ── Mode dispatch ────────────────────────────────────────────
 52→  // Panel: all entities respond in parallel, each seeing only its own history
 53→  // Roundtable: entities respond sequentially, each seeing prior responses (Step 7c)
 54→  // Directed: @-mention routes to a specific entity (Step 7d)
 55→
 56→  if (channel.mode === 'roundtable') {
 57→    // Roundtable: create placeholders, then stream sequentially
 58→    const db = getDb();
 59→    const txn = db.transaction(() => {
 60→      const userMsg = insertMessage(channelId, 'user', content.trim(), 'complete');
 61→      const assistants = entities.map((entity) => {
 62→        const msg = insertMessage(channelId, 'assistant', '', 'streaming', entity.model, entity.id);
 63→        return { assistantMessageId: msg.id, entityId: entity.id, model: entity.model };
 64→      });
 65→      return { userMsg, assistants };
 66→    });
 67→    const { userMsg, assistants } = txn();
 68→
 69→    // Fire sequential roundtable orchestration (don't await — runs in background)
 70→    streamClaudeRoundtable(
 71→      channelId,
 72→      assistants.map((a) => ({
 73→        assistantMessageId: a.assistantMessageId,
 74→        entity: entities.find((e) => e.id === a.entityId)!,
 75→      })),
 76→      channel.systemPrompt
 77→    );
 78→
 79→    return c.json({ userMessageId: userMsg.id, assistants });
 80→  }
 81→
 82→  if (channel.mode === 'directed') {
 83→    // Directed: @-mention routes to specific entity(ies)
 84→    const mentioned = resolveMentions(content, entities);
 85→
 86→    if (mentioned.length === 0) {
 87→      // No valid @-mention found — tell the user what's available
 88→      const names = entities.map((e) => `@${e.name}`).join(', ');
 89→      return c.json({
 90→        error: `No entity mentioned. Use @EntityName to direct your message. Available: ${names}`,
 91→      }, 400);
 92→    }
 93→
 94→    // Create user message + placeholders only for mentioned entities
 95→    const db = getDb();
 96→    const txn = db.transaction(() => {
 97→      const userMsg = insertMessage(channelId, 'user', content.trim(), 'complete');
 98→      const assistants = mentioned.map((entity) => {
 99→        const msg = insertMessage(channelId, 'assistant', '', 'streaming', entity.model, entity.id);
100→        return { assistantMessageId: msg.id, entityId: entity.id, model: entity.model };
101→      });
102→      return { userMsg, assistants };
103→    });
104→    const { userMsg, assistants } = txn();
105→
106→    // Fire off streams for mentioned entities (parallel, panel-like isolation)
107→    for (const assistant of assistants) {
108→      const entity = mentioned.find((e) => e.id === assistant.entityId)!;
109→      streamClaude(channelId, assistant.assistantMessageId, entity, channel.systemPrompt);
110→    }
111→
112→    return c.json({ userMessageId: userMsg.id, assistants });
113→  }
114→
115→  // ── Panel mode (default) ────────────────────────────────────
116→  // Create user message + N assistant placeholders in a single transaction
117→  const db = getDb();
118→  const txn = db.transaction(() => {
119→    const userMsg = insertMessage(channelId, 'user', content.trim(), 'complete');
120→    const assistants = entities.map((entity) => {
121→      const msg = insertMessage(channelId, 'assistant', '', 'streaming', entity.model, entity.id);
122→      return { assistantMessageId: msg.id, entityId: entity.id, model: entity.model };
123→    });
124→    return { userMsg, assistants };
125→  });
126→  const { userMsg, assistants } = txn();
127→
128→  // Fire off N parallel streams (don't await)
129→  for (const assistant of assistants) {
130→    const entity = entities.find((e) => e.id === assistant.entityId)!;
131→    streamClaude(channelId, assistant.assistantMessageId, entity, channel.systemPrompt);
132→  }
133→
134→  return c.json({ userMessageId: userMsg.id, assistants });
135→});
