189→  const entities = getChannelEntities(channelId);
190→  if (entities.length === 0) {
191→    return c.json({ error: 'No entities assigned to this channel' }, 400);
192→  }
193→
194→  if (channel.mode === 'roundtable') {
195→    // Roundtable: delete ALL assistant messages from the last round, redo the whole round
196→    const lastRound = getLastRoundAssistantMessages(channelId);
197→    if (lastRound.length === 0) {
198→      return c.json({ error: 'No assistant messages to regenerate' }, 404);
199→    }
200→
201→    const db = getDb();
202→    const txn = db.transaction(() => {
203→      for (const msg of lastRound) deleteMessage(msg.id);
204→      return entities.map((entity) => {
205→        const msg = insertMessage(channelId, 'assistant', '', 'streaming', entity.model, entity.id);
206→        return { assistantMessageId: msg.id, entityId: entity.id, model: entity.model };
207→      });
208→    });
209→    const assistants = txn();
210→
211→    streamClaudeRoundtable(
212→      channelId,
213→      assistants.map((a) => ({
214→        assistantMessageId: a.assistantMessageId,
215→        entity: entities.find((e) => e.id === a.entityId)!,
216→      })),
217→      channel.systemPrompt
218→    );
219→
220→    return c.json({
221→      assistantMessageId: assistants[0].assistantMessageId,
222→      model: assistants[0].model,
223→      assistants,
224→    });
225→  }
226→
227→  // Panel and directed modes: regenerate just the last assistant message(s)
228→  // For directed, there may be multiple assistant messages from the last user turn
229→  // but we regenerate the same set. For now, single-entity regenerate works for both.
230→  const lastAssistant = getLastAssistantMessage(channelId);
231→  if (!lastAssistant) {
232→    return c.json({ error: 'No assistant message to regenerate' }, 404);
233→  }
234→
235→  deleteMessage(lastAssistant.id);
236→
237→  // If the message had an entity, regenerate with that entity; otherwise use first channel entity
238→  const entity = lastAssistant.entityId
239→    ? entities.find((e) => e.id === lastAssistant.entityId) || entities[0]
240→    : entities[0];
241→
242→  if (!entity) {
243→    return c.json({ error: 'Entity not found for regeneration' }, 404);
244→  }
245→
246→  const assistantMsg = insertMessage(channelId, 'assistant', '', 'streaming', entity.model, entity.id);
247→  streamClaude(channelId, assistantMsg.id, entity, channel.systemPrompt);
248→
249→  return c.json({
250→    assistantMessageId: assistantMsg.id,
251→    model: entity.model,
252→    assistants: [{ assistantMessageId: assistantMsg.id, entityId: entity.id, model: entity.model }],
253→  });
254→});
255→
256→// SSE endpoint to observe a streaming message
257→app.get('/messages/:id/stream', (c) => {
258→  const messageId = c.req.param('id');
259→
260→  return streamSSE(c, async (stream) => {
261→    // Try to find an active emitter — it may not exist yet (roundtable entities
262→    // that haven't started) or may have already completed.
263→    let emitter = activeStreams.get(messageId);
264→
265→    if (!emitter) {
266→      // No emitter. Check DB to distinguish "already done" from "not started yet".
267→      const msg = getMessage(messageId);
268→
269→      if (!msg || msg.status === 'complete' || msg.status === 'error') {
270→        // Already finished — send the final content immediately
271→        const type = msg?.status === 'error' ? 'error' : 'message_complete';
272→        await stream.writeSSE({
273→          data: JSON.stringify({
274→            type,
275→            messageId,
276→            content: msg?.content ?? '',
277→          } satisfies StreamEvent),
278→        });
279→        return;
280→      }
281→
282→      // Status is 'streaming' but no emitter — the stream hasn't started yet
283→      // (e.g., roundtable entity waiting for its turn). Poll until it appears.
284→      const maxWait = 120_000; // 2 minutes
285→      const pollInterval = 200;
286→      const deadline = Date.now() + maxWait;
287→
288→      while (Date.now() < deadline) {
289→        emitter = activeStreams.get(messageId);
290→        if (emitter) break;
291→
292→        // Check if it completed while we were waiting (another race)
293→        const fresh = getMessage(messageId);
294→        if (fresh && (fresh.status === 'complete' || fresh.status === 'error')) {
295→          const type = fresh.status === 'error' ? 'error' : 'message_complete';
296→          await stream.writeSSE({
297→            data: JSON.stringify({
298→              type,
299→              messageId,
300→              content: fresh.content ?? '',
301→            } satisfies StreamEvent),
302→          });
303→          return;
304→        }
305→
306→        await new Promise((r) => setTimeout(r, pollInterval));
307→      }
308→
309→      if (!emitter) {
310→        // Timed out waiting — send whatever the DB has
311→        const final = getMessage(messageId);
312→        await stream.writeSSE({
313→          data: JSON.stringify({
314→            type: 'message_complete',
315→            messageId,
316→            content: final?.content ?? '',
317→          } satisfies StreamEvent),
318→        });
319→        return;
320→      }
321→    }
322→
323→    // Forward events from the in-memory emitter to SSE
324→    await new Promise<void>((resolve) => {
325→      // Safety: resolve if emitter is removed (stream completed between our check and subscribe)
326→      const interval = setInterval(() => {
327→        if (!activeStreams.has(messageId)) {
328→          clearInterval(interval);
329→          emitter!.off('data', onData);
330→          resolve();
331→        }
332→      }, 500);
333→
334→      const onData = async (event: StreamEvent) => {
335→        try {
336→          await stream.writeSSE({ data: JSON.stringify(event) });
337→        } catch {
338→          // Client disconnected
339→          clearInterval(interval);
340→          emitter!.off('data', onData);
341→          resolve();
342→          return;
343→        }
344→        if (event.type === 'message_complete' || event.type === 'error') {
345→          clearInterval(interval);
346→          emitter!.off('data', onData);
347→          resolve();
348→        }
349→      };
350→
351→      emitter!.on('data', onData);
352→    });
353→  });
354→});
355→
356→export { app as messageRoutes };
