 15→/** Seed a channel with messages and artifacts for testing stats queries */
 16→function seedImportedChannel(opts?: { source?: string; cwd?: string }) {
 17→  const db = getDb();
 18→  const channelId = uuidv4();
 19→  const source = opts?.source ?? 'claude-code';
 20→  const cwd = opts?.cwd ?? '/home/user/my-project';
 21→  const meta = JSON.stringify({
 22→    originalSessionId: uuidv4(),
 23→    cwd,
 24→    importedAt: new Date().toISOString(),
 25→  });
 26→
 27→  db.prepare(
 28→    `INSERT INTO channels (id, name, source, source_metadata, created_at)
 29→     VALUES (?, ?, ?, ?, datetime('now'))`
 30→  ).run(channelId, `test-${channelId.slice(0, 6)}`, source, meta);
 31→
 32→  // Insert messages: 3 user, 2 assistant
 33→  const msgIds: string[] = [];
 34→  for (let i = 0; i < 5; i++) {
 35→    const msgId = uuidv4();
 36→    msgIds.push(msgId);
 37→    db.prepare(
 38→      `INSERT INTO messages (id, channel_id, role, content, status, created_at)
 39→       VALUES (?, ?, ?, ?, 'complete', datetime('now', '+${i} seconds'))`
 40→    ).run(msgId, channelId, i % 2 === 0 ? 'user' : 'assistant', `msg ${i}`);
 41→  }
 42→
 43→  // Insert artifacts on assistant messages (msgIds[1] and msgIds[3])
 44→  const artifacts = [
 45→    { msgId: msgIds[1], type: 'tool_use', toolName: 'Read', summary: 'src/App.tsx' },
 46→    { msgId: msgIds[1], type: 'tool_use', toolName: 'Read', summary: 'src/index.ts' },
 47→    { msgId: msgIds[1], type: 'tool_use', toolName: 'Bash', summary: 'npm test' },
 48→    { msgId: msgIds[1], type: 'tool_result', toolName: 'Read', summary: null },
 49→    { msgId: msgIds[1], type: 'thinking', toolName: null, summary: null },
 50→    { msgId: msgIds[3], type: 'tool_use', toolName: 'Grep', summary: '*.ts' },
 51→    { msgId: msgIds[3], type: 'tool_result', toolName: 'Grep', summary: null },
 52→    { msgId: msgIds[3], type: 'thinking', toolName: null, summary: null },
 53→    { msgId: msgIds[3], type: 'image', toolName: null, summary: null },
 54→  ];
 55→
 56→  for (const a of artifacts) {
 57→    db.prepare(
 58→      `INSERT INTO message_artifacts (id, message_id, type, tool_name, input_summary)
 59→       VALUES (?, ?, ?, ?, ?)`
 60→    ).run(uuidv4(), a.msgId, a.type, a.toolName, a.summary);
 61→  }
 62→
 63→  return { channelId, msgIds };
 64→}
