  1→// ── ZIP extraction for claude.ai email exports ─────────────────
  2→// Extracts conversation JSON files and project metadata from a claude.ai export ZIP.
  3→
  4→import AdmZip from 'adm-zip';
  5→
  6→export interface ConversationFile {
  7→  filename: string;
  8→  conversation: unknown;
  9→}
 10→
 11→export interface ProjectInfo {
 12→  uuid: string;
 13→  name: string;
 14→  documentCount?: number;
 15→}
 16→
 17→export interface MemoryItem {
 18→  uuid: string;
 19→  content: string;
 20→  createdAt?: string;
 21→}
 22→
 23→export interface ClaudeAiExport {
 24→  conversations: ConversationFile[];
 25→  /** Map from project UUID → project info (from projects.json) */
 26→  projects: Map<string, ProjectInfo>;
 27→  /** Memory items from memories.json */
 28→  memories: MemoryItem[];
 29→}
 30→
 31→/**
 32→ * Extract conversations and projects from a claude.ai data export ZIP buffer.
 33→ *
 34→ * Supports two conversation formats:
 35→ * 1. Single `conversations.json` at root — array of conversation objects (current export format)
 36→ * 2. Individual .json files inside a `conversations/` directory (legacy/anticipated format)
 37→ *
 38→ * Also extracts `projects.json` to resolve project names for conversations.
 39→ * Skips malformed JSON files gracefully.
 40→ */
 41→export function extractFromZip(zipBuffer: Buffer): ClaudeAiExport {
 42→  const zip = new AdmZip(zipBuffer);
 43→  const entries = zip.getEntries();
 44→  const conversations: ConversationFile[] = [];
 45→  const projects = new Map<string, ProjectInfo>();
 46→  const memories: MemoryItem[] = [];
 47→
 48→  for (const entry of entries) {
 49→    if (entry.isDirectory) continue;
 50→
 51→    const name = entry.entryName;
 52→    if (!name.endsWith('.json')) continue;
 53→
 54→    try {
 55→      const content = entry.getData().toString('utf-8');
 56→      const parsed = JSON.parse(content);
 57→      const basename = name.split('/').pop();
 58→
 59→      // projects.json — array of project objects with uuid and name
 60→      if (basename === 'projects.json' && Array.isArray(parsed)) {
 61→        for (const proj of parsed) {
 62→          if (proj && proj.uuid && proj.name) {
 63→            const docs = Array.isArray(proj.docs) ? proj.docs : [];
 64→            projects.set(proj.uuid, {
 65→              uuid: proj.uuid,
 66→              name: proj.name,
 67→              documentCount: docs.length,
 68→            });
 69→          }
 70→        }
 71→        continue;
